const items = $input.all();

// Manual testing mein pehla available record force-send hoga
const isManualTest = $('Manual Reminder Test').isExecuted;

if (isManualTest) {
  if (items.length === 0) {
    throw new Error('Reminder queue mein testing ke liye koi interview record nahi mila.');
  }

  return [{
    json: {
      ...items[0].json,
      reminder_due: true,
      test_mode: true
    }
  }];
}

// Hourly production execution ke asli rules
const now = Date.now();
const next24Hours = now + (24 * 60 * 60 * 1000);
const twelveHoursAgo = now - (12 * 60 * 60 * 1000);

return items
  .filter(item => {
    const row = item.json;
    const start = new Date(row.scheduled_start).getTime();
    const lastReminder = row.last_reminder_at
      ? new Date(row.last_reminder_at).getTime()
      : null;

    return (
      start > now &&
      start <= next24Hours &&
      Number(row.reminder_count || 0) < 2 &&
      (!lastReminder || lastReminder <= twelveHoursAgo)
    );
  })
  .map(item => ({
    json: {
      ...item.json,
      reminder_due: true,
      test_mode: false
    }
  }));

const row = $json;
const start = new Date(row.scheduled_start);
const end = new Date(row.scheduled_end);
const format = date => date.toISOString().replace('T', ' ').replace('.000Z', ' UTC').replace('Z', ' UTC');
const meetingText = row.meeting_url ? `Meeting link: ${row.meeting_url}` : 'Meeting link will be shared by the hiring team.';
return [{ json: { ...row, email_to: row.candidate_email, email_subject: `Interview reminder - ${row.position_title}`, email_message: `Hello ${row.candidate_name},

This is a reminder for your ${row.position_title} interview.

Start: ${format(start)}
End: ${format(end)}
${meetingText}

Interview code: ${row.interview_code}
Status: ${row.interview_status}

Regards,
NovaTech Solutions Recruitment Team`, new_reminder_count: Number(row.reminder_count || 0) + 1, reminder_sent_at: new Date().toISOString() } }];
